/** Native work must scale with final pages and reduced metadata, not a discarded per-edge delta generation. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbInitialRunImportDirectAdjacencyWorkTest {
	@TempDir
	Path directory;

	@Test
	@Timeout(120)
	void denseInitialImportWritesFinalPagesAndEachMetadataKeyOnce() throws Exception {
		var vf = SimpleValueFactory.getInstance();
		Set<Statement> expected = new HashSet<>();
		IRI graph = vf.createIRI("urn:direct-load:graph");
		for (int p = 0; p < 2; p++) {
			for (int s = 0; s < 32; s++) {
				for (int o = 0; o < 32; o++) {
					IRI subject = vf.createIRI("urn:direct-load:s" + s);
					IRI predicate = vf.createIRI("urn:direct-load:p" + p);
					IRI object = vf.createIRI("urn:direct-load:o" + o);
					expected.add(vf.createStatement(subject, predicate, object));
					expected.add(vf.createStatement(subject, predicate, object, graph));
				}
			}
		}
		assertThat(expected).hasSize(4096);
		long previousChunkBytes = LmdbInitialRunImport.chunkBytesForTest;
		LmdbInitialRunImport.chunkBytesForTest = 16L << 10;
		Work work = new Work();
		LmdbStore sail = new LmdbStore(directory.toFile(), config());
		try {
			sail.init();
			LmdbSailStore backing = sail.getBackingStore();
			TripleStore triples = backing.getTripleStore();
			int[] databases = triples.getTxnManager().doWith((stack, txn) -> {
				LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(txn);
				return new int[] { adjacency.pagesDbi(), adjacency.metadataDbi(), adjacency.deltasDbi() };
			});
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				for (int repetition = 0; repetition < 2; repetition++) {
					int row = 0;
					for (Statement statement : expected) {
						writer.addStatement(statement.getSubject(), statement.getPredicate(), statement.getObject(),
								statement.getContext());
						if (++row % 256 == 0) {
							// A real owner checkpoint makes provisional rows spillable without completing the import.
							backing.flushNonePending(writer, false);
						}
					}
					assertThat(backing.isInitialRunImportActive()).isTrue();
					try (var files = Files.list(directory.resolve(LmdbInitialRunImport.RUN_DIRECTORY_NAME))) {
						assertThat(files.filter(path -> path.getFileName().toString().startsWith("triples-"))
								.count()).as("both copies reach multiple retained spill files")
										.isGreaterThanOrEqualTo(2);
					}
				}
				// Mockito static scopes are thread-local. Install and close them on the actual native owner,
				// including rollback/failure, rather than observing the waiting connection thread.
				backing.beforeAsyncOperationForTest = () -> work.open(triples, databases);
				backing.afterAsyncTransactionForTest = work::close;
				backing.afterAsyncFailureForTest = ignored -> work.close();
				writer.commit();
			}
			assertThat(backing.initialRunImportsCompleted()).isEqualTo(1);
			assertContents(sail, expected);
		} finally {
			try {
				sail.shutDown();
			} finally {
				LmdbInitialRunImport.chunkBytesForTest = previousChunkBytes;
			}
		}
		assertThat(work.activeScopes.get()).as("every writer-thread observer was closed").isZero();
		assertThat(work.scopes.get()).as("actual async writer hit proof").isPositive();
		LmdbStore reopened = new LmdbStore(directory.toFile(), config());
		try {
			reopened.init();
			assertContents(reopened, expected);
		} finally {
			reopened.shutDown();
		}
		System.out.printf(
				"DIRECT_INITIAL_WORK pages=%d metadata=%d deltaPuts=%d deltaDeletes=%d metadataGets=%d dirty=%d%n",
				work.pages.get(), work.metadata.get(), work.deltaPuts.get(), work.deltaDeletes.get(),
				work.metadataGets.get(), work.dirty.get());
		assertThat(work.deltaPuts.get()).as("fresh construction must not create per-edge deltas").isZero();
		assertThat(work.deltaDeletes.get()).as("fresh construction must not compact a disposable delta generation")
				.isZero();
		assertThat(work.dirty.get()).as("no dirty/candidate metadata during direct construction").isZero();
		assertThat(work.pages.get()).as("2 predicates x 2 pages x 2 directions").isEqualTo(8);
		// 1 total + 2P + 2(Rout+Rin) + 2C + V = 1+4+256+4+67.
		assertThat(work.metadata.get()).as("one put per reduced non-format metadata key").isEqualTo(332);
		assertThat(work.metadataKeys).hasSize(332);
		assertThat(work.metadataKeys.values()).allSatisfy(count -> assertThat(count.get()).isEqualTo(1));
		assertThat(work.metadataGets.get()).as("constant admission checks, not per-edge read-modify-write")
				.isLessThanOrEqualTo(16);
	}

	private static void assertContents(LmdbStore sail, Set<Statement> expected) {
		try (LmdbStoreConnection reader = (LmdbStoreConnection) sail.getConnection();
				var statements = reader.getStatements(null, null, null, false)) {
			var actual = statements.stream().toList();
			assertThat(actual).hasSize(expected.size());
			assertThat(new HashSet<>(actual)).isEqualTo(expected);
			assertThat(reader.size()).isEqualTo(expected.size());
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc").setBulkOperationSize(64)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false)
				.setTripleDBSize(64L << 20)
				.setValueDBSize(16L << 20)
				.setForceSync(true);
	}

	private static final class Work {
		final Map<String, AtomicInteger> metadataKeys = new ConcurrentHashMap<>();
		final AtomicLong pages = new AtomicLong();
		final AtomicLong metadata = new AtomicLong();
		final AtomicLong deltaPuts = new AtomicLong();
		final AtomicLong deltaDeletes = new AtomicLong();
		final AtomicLong metadataGets = new AtomicLong();
		final AtomicLong dirty = new AtomicLong();
		final AtomicInteger activeScopes = new AtomicInteger();
		final AtomicInteger scopes = new AtomicInteger();
		final ThreadLocal<MockedStatic<LMDB>> observer = new ThreadLocal<>();

		void open(TripleStore store, int[] db) {
			if (observer.get() != null) {
				return;
			}
			long writer = store.writeTxn;
			Map<Long, Integer> cursors = new HashMap<>();
			int[] depth = { 0 };
			observer.set(mockStatic(LMDB.class, call -> {
				if (depth[0]++ != 0) {
					try {
						return call.callRealMethod();
					} finally {
						depth[0]--;
					}
				}
				try {
					String method = call.getMethod().getName();
					if (method.equals("mdb_cursor_open")) {
						Object result = call.callRealMethod();
						if ((int) result == LMDB.MDB_SUCCESS && (long) call.getArgument(0) == writer) {
							cursors.put(((PointerBuffer) call.getArgument(2)).get(0), call.getArgument(1));
						}
						return result;
					}
					if (method.equals("mdb_cursor_close")) {
						cursors.remove((long) call.getArgument(0));
					}
					int database = -1;
					MDBVal key = null;
					boolean put = method.equals("mdb_put") || method.equals("mdb_cursor_put");
					if (method.equals("mdb_put") || method.equals("mdb_get") || method.equals("mdb_del")) {
						if ((long) call.getArgument(0) == writer) {
							database = call.getArgument(1);
							key = call.getArgument(2);
						}
					} else if (method.equals("mdb_cursor_put") || method.equals("mdb_cursor_del")
							|| method.equals("mdb_cursor_get")) {
						database = cursors.getOrDefault((long) call.getArgument(0), -1);
						if (put) {
							key = call.getArgument(1);
						}
					}
					Object result = call.callRealMethod();
					if (database >= 0 && (int) result == LMDB.MDB_SUCCESS) {
						if (put && database == db[0]) {
							pages.incrementAndGet();
						}
						if (put && database == db[1] && key.mv_size() > 1) {
							metadata.incrementAndGet();
							byte[] bytes = new byte[(int) key.mv_size()];
							key.mv_data().duplicate().get(bytes);
							metadataKeys
									.computeIfAbsent(HexFormat.of().formatHex(bytes), ignored -> new AtomicInteger())
									.incrementAndGet();
							int type = Byte.toUnsignedInt(key.mv_data().get(0));
							if (type >= 8 && type <= 10) {
								dirty.incrementAndGet();
							}
						}
						if (put && database == db[2]) {
							deltaPuts.incrementAndGet();
						}
						if ((method.equals("mdb_del") || method.equals("mdb_cursor_del")) && database == db[2]) {
							deltaDeletes.incrementAndGet();
						}
					}
					if ((method.equals("mdb_get") || method.equals("mdb_cursor_get")) && database == db[1]) {
						metadataGets.incrementAndGet();
					}
					return result;
				} finally {
					depth[0]--;
				}
			}));
			scopes.incrementAndGet();
			activeScopes.incrementAndGet();
		}

		void close() {
			MockedStatic<LMDB> scope = observer.get();
			if (scope != null) {
				scope.close();
				observer.remove();
				activeScopes.decrementAndGet();
			}
		}
	}
}
